import os, re

def load():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    lines = t.split('\n')
    idxs = []
    for i, line in enumerate(lines):
        if i < len(lines) - 1:
            next_line = lines[i + 1]
            if 'Demo pair' in next_line or 'Test input' in next_line:
                idxs.append((i, line))
    return lines, idxs

def extract_pair(idx, idxs):
    lines, pairs_loaded = load()
    if idx < len(lines) - 1:
        next_lines = lines[idx + 1:lines.index(lines[0] if lines else '')]
        h, w = re.search(r'\((\d+)x(\d+)\)', lines[idx]).group(1, 2)
        rows = [l.strip() for l in next_lines if l.strip()][:h if h else w]
        if len(rows) > 0 and all(any(c.isdigit() for c in r) for r in rows[:h]):
            return [[int(c) for c in r.split()] for r in rows[:h]]
    return None

